<?php
declare(strict_types=1);
(static function (): void {
    require_once __DIR__ . '/../cloud/McpService.php';
    $db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
    $db->exec("CREATE TABLE devices(id TEXT PRIMARY KEY,user_id INTEGER,label TEXT,platform TEXT,last_seen_at TEXT,revoked_at TEXT)");
    $db->exec("CREATE TABLE pairing_requests(id TEXT PRIMARY KEY,owner_device TEXT,requester_device TEXT,status TEXT,created_at TEXT,expires_at TEXT)");
    $db->exec("CREATE TABLE device_pairings(id INTEGER PRIMARY KEY,owner_device TEXT,peer_device TEXT,scopes TEXT,presence_paused_at TEXT,revoked_at TEXT)");
    $db->exec("CREATE TABLE cloud_teams(id INTEGER PRIMARY KEY,owner_user_id INTEGER,name TEXT,created_at TEXT)");
    $db->exec("CREATE TABLE cloud_team_members(team_id INTEGER,user_id INTEGER,role TEXT,created_at TEXT)");
    $db->exec("CREATE TABLE cloud_resources(id TEXT PRIMARY KEY,owner_user_id INTEGER,owner_device_id TEXT,kind TEXT,name TEXT,provider TEXT,model TEXT,endpoint_class TEXT,operations_json TEXT,metadata_json TEXT,capacity_json TEXT,data_classification TEXT,locality TEXT,secret_ref TEXT,health_status TEXT,health_at TEXT,published INTEGER,revoked_at TEXT)");
    $db->exec("CREATE TABLE cloud_resource_grants(id TEXT PRIMARY KEY,resource_id TEXT,grantee_type TEXT,grantee_id TEXT,operations_json TEXT,quota_limit INTEGER,concurrency_limit INTEGER,expires_at TEXT,status TEXT,generation INTEGER,created_at TEXT,revoked_at TEXT)");
    $db->exec("INSERT INTO devices VALUES('d1',1,'Amr Mac','macOS',datetime('now'),NULL),('d2',2,'Team PC','Windows',datetime('now'),NULL),('d3',1,'Revoked','Linux',datetime('now'),'2026-01-01')");
    $db->exec("INSERT INTO cloud_teams VALUES(10,1,'Core Team','2026-01-01'),(20,2,'Other Team','2026-01-01')");
    $db->exec("INSERT INTO cloud_team_members VALUES(10,1,'owner','2026-01-01'),(20,1,'member','2026-01-01')");
    $insert=$db->prepare('INSERT INTO cloud_resources VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NULL)');
    $resource=static function(string $id,int $owner,string $name,int $published)use($insert):void{$insert->execute([$id,$owner,'d1','model',$name,'ollama','qwen','local','["infer"]','{"endpoint":"local"}','{"ram_mb":4096}','internal','device','vault://secret','online',date('Y-m-d H:i:s'),$published]);};
    $resource('r-owned',1,'Owned',0);$resource('r-user',2,'User shared',1);$resource('r-team',2,'Team shared',1);$resource('r-device',2,'Device shared',1);$resource('r-hidden',2,'Not shared',1);
    $grant=$db->prepare('INSERT INTO cloud_resource_grants VALUES(?,?,?,?,?,100,2,?,\'active\',1,?,NULL)');
    $grant->execute(['g-user','r-user','user','1','["infer"]','2099-01-01','2026-01-01']);
    $grant->execute(['g-team','r-team','team','10','["infer"]','2099-01-01','2026-01-01']);
    $grant->execute(['g-device','r-device','device','d1','["infer"]','2099-01-01','2026-01-01']);
    $grant->execute(['g-owned','r-owned','user','2','["infer"]','2099-01-01','2026-01-01']);
    $grant->execute(['g-expired','r-hidden','user','1','["infer"]','2000-01-01','2026-01-01']);
    $db->exec("INSERT INTO device_pairings VALUES(1,'d1','d2','[\"presence\",\"terminal.request\"]',NULL,NULL)");
    $db->exec("INSERT INTO pairing_requests VALUES('p1','d1','d2','pending',datetime('now'),datetime('now','+5 minutes'))");
    $service=new DcpCloudMcpService($db);
    ok(count($service->tools(['cloud.devices.read']))===2,'Cloud MCP tools/list is filtered to the token device-read scope');
    ok(count($service->tools(['cloud.resources.read']))===1&&$service->tools(['cloud.resources.read'])[0]['name']==='dcp_cloud_resource_discover','Cloud MCP tools/list exposes resource discovery only to its matching scope');
    ok(!DcpCloudMcpService::hasScope(['cloud.devices.read'],'cloud.grants.read'),'Cloud MCP scopes do not imply unrelated grants access');
    ok(DcpCloudMcpService::hasScope(['*'],'cloud.grants.read')&&!DcpCloudMcpService::hasScope(['cloud.devices.read'],'cloud.resources.read'),'Legacy full account tokens preserve access while scoped tokens remain least-privilege');
    $devices=$service->call('dcp_cloud_list_devices',[],1);ok(count($devices['devices'])===1&&$devices['devices'][0]['id']==='d1','Cloud MCP lists only active devices owned by the account');
    $pairings=$service->call('dcp_cloud_pairing_overview',[],1);ok(count($pairings['pending_requests'])===1&&count($pairings['pairings'])===1,'Cloud MCP pairing overview is account-scoped and filters revoked devices');
    $resources=$service->call('dcp_cloud_resource_discover',['kind'=>'model','limit'=>20],1);$ids=array_column($resources['resources'],'id');sort($ids);ok($ids===['r-device','r-owned','r-team','r-user'],'Cloud MCP resource discovery honors owner, user, team and device grants while rejecting expired/unshared grants');
    ok(!array_key_exists('secret_ref',$resources['resources'][0])&&!str_contains(json_encode($resources),'vault://secret'),'Cloud MCP never discloses owner-local secret references');
    $teams=$service->call('dcp_cloud_list_teams',[],1);ok(count($teams['teams'])===2,'Cloud MCP lists only teams the account belongs to');
    $grants=$service->call('dcp_cloud_list_resource_grants',['limit'=>20],1);ok(count($grants['grants'])===1,'Cloud MCP grant inventory is limited to resources owned by the account');
    $bounded=$service->call('dcp_cloud_resource_discover',['limit'=>1000],1);ok($bounded['count']<=50,'Cloud MCP clamps resource query bounds to at most 50 rows');
})();
